/// Icon-only close control; Kit routes Cancel through the host's veto callback.
pub fn dialog_close(id: impl Into<ElementId>, cx: &App) -> Button {
    let t = UiTheme::read(cx);
    Button::new(id)
        .aria_label("Close")
        .variant(ButtonVariant::Ghost)
